const body = $input.first().json.body || {};
const text = String(body.text || body.event || '').trim();
const source = String(body.source || 'manual')
  .trim()
  .replace(/[^a-zA-Z0-9 _.-]/g, '')
  .slice(0, 100) || 'manual';

if (!text) {
  return [{ json: {
    ok: false,
    statusCode: 400,
    error: "Body must include a non-empty 'text' field.",
  } }];
}
if (text.length > 1000) {
  return [{ json: {
    ok: false,
    statusCode: 400,
    error: "Event text exceeds the 1000-character limit.",
  } }];
}

const state = $getWorkflowStaticData('global');
const events = Array.isArray(state.events) ? state.events : [];
if (events.length >= 100) {
  return [{ json: {
    ok: false,
    statusCode: 429,
    error: 'The digest queue is full; run the digest before adding more events.',
  } }];
}

const now = new Date();
const event = {
  id: now.toISOString() + '-' + Math.random().toString(16).slice(2, 10),
  captured_at: now.toISOString(),
  source,
  text,
};
events.push(event);
state.events = events;

return [{ json: {
  ok: true,
  statusCode: 202,
  accepted: event,
  pending_events: state.events.length,
} }];

const state = $getWorkflowStaticData('global');
const events = Array.isArray(state.events) ? state.events : [];
const snapshot = events.slice(0, 100);

return [{ json: {
  has_events: snapshot.length > 0,
  event_count: snapshot.length,
  event_ids: snapshot.map((event) => event.id),
  events: snapshot,
  digest_input: snapshot
    .map((event, index) =>
      `[${index + 1}] ${event.captured_at} (${event.source}) ${event.text}`
    )
    .join('\n'),
} }];

const response = $input.first().json || {};
const snapshot = $('Load Pending Events').first().json;
const summary = response.choices?.[0]?.message?.content;
if (typeof summary !== 'string' || !summary.trim()) {
  throw new Error('llama-server returned no digest text');
}

const date = new Date().toISOString().slice(0, 10);
const path = `/home/node/.n8n/daily-digest-${date}.md`;
const markdown = [
  `# Daily Digest - ${date}`,
  '',
  `_Generated from ${snapshot.event_count} captured events._`,
  '',
  summary.trim(),
  '',
  '## Source events',
  ...snapshot.events.map((event) =>
    `- ${event.captured_at} [${event.source}] ${event.text}`
  ),
  '',
].join('\n');

return [{ json: {
  path,
  filename: path.split('/').pop(),
  markdown,
  event_ids: snapshot.event_ids,
  event_count: snapshot.event_count,
} }];

const digest = $('Compose Digest File').first().json;
const included = new Set(digest.event_ids);
const state = $getWorkflowStaticData('global');
const current = Array.isArray(state.events) ? state.events : [];
state.events = current.filter((event) => !included.has(event.id));

return [{ json: {
  status: 'saved',
  path: digest.path,
  events_included: digest.event_count,
  pending_events: state.events.length,
} }];
